// ---------------------------------------------------------------------
// PANTALLA: CONFIGURAR ENSAYO
// ---------------------------------------------------------------------
let selectedCount = null;
function renderEnsayoSetup(area){
  ensayoArea = area === 'mat' ? 'mat' : 'cien';
  const isMat = ensayoArea === 'mat';
  const pool = isMat ? MATH_ALL_QUESTIONS : ALL_QUESTIONS;
  const areaLabel = isMat ? 'Matemática (M1)' : 'Ciencias (Biología, Física y Química)';
  const opts = isMat ? [5,10,15,20,30,65] : [5,10,15,30,60,80];
  selectedCount = null;
  app.innerHTML = `
    <div class="crumbs"><span class="note" style="font-family:'Space Grotesk',sans-serif; font-size:12px; color:var(--muted); cursor:pointer;" onclick="go(renderEnsayoAreaSelect)">← Ensayos</span></div>
    <div class="section-head">
      <h2>Ensayo de ${areaLabel}</h2>
      <div class="note">${pool.length} preguntas disponibles en el banco de ${areaLabel}</div>
    </div>
    <p style="color:var(--muted); font-family:'Space Grotesk',sans-serif; font-size:14px; max-width:560px;">
      Elige cuántas preguntas quieres responder. Cada vez que generes un ensayo, las preguntas y el orden de las alternativas se sortean de nuevo.
    </p>
    <div class="count-grid" id="countGrid">
      ${opts.map(n=>`<div class="count-opt" data-n="${n}" onclick="pickCount(${n})"><span class="n">${n}</span><span class="l">preguntas</span></div>`).join('')}
    </div>
    <div class="btn-row">
      <button class="btn btn-primary" id="startEnsayoBtn" disabled onclick="launchEnsayo()">Generar ensayo</button>
    </div>
  `;
}
function pickCount(n){
  selectedCount = n;
  document.querySelectorAll('.count-opt').forEach(el=>{
    el.classList.toggle('selected', Number(el.dataset.n)===n);
  });
  document.getElementById('startEnsayoBtn').disabled = false;
}
function launchEnsayo(){
  if(!selectedCount) return;
  const isMat = ensayoArea === 'mat';
  const pool = isMat ? MATH_ALL_QUESTIONS : ALL_QUESTIONS;
  const areaLabel = isMat ? 'Matemática' : 'Ciencias';
  const picked = sample(pool, selectedCount);
  go(renderQuizScreen, [{
    title:`Ensayo de ${areaLabel} · ${selectedCount} preguntas`,
    questions: picked,
    timed:false,
    onFinish:(correct,total)=>{
      progress.ensayos.unshift({date:new Date().toISOString(), total, correct, area: isMat?'mat':'cien'});
      if(progress.ensayos.length>50) progress.ensayos.length=50;
      saveProgress();
    },
    onRepeat:()=>launchEnsayo(),
    repeatLabel:'Generar otro ensayo'
  }]);
}

// ---------------------------------------------------------------------
// MOTOR DE CUESTIONARIOS (usado por ensayos, subtemas, unidades y examen final)
// ---------------------------------------------------------------------
let quizState = null;

function prepQuestions(rawQuestions){
  // Baraja el orden de las preguntas y, dentro de cada una, el de las alternativas
  return shuffle(rawQuestions).map(orig=>{
    const optIdx = orig.o.map((_,i)=>i);
    const shuffled = shuffle(optIdx);
    const newOptions = shuffled.map(i=>orig.o[i]);
    const newCorrect = shuffled.indexOf(orig.c);
    return {
      q: orig.q, o: newOptions, c: newCorrect, e: orig.e,
      unitId: orig.unitId, subId: orig.subId,
      chosen: null
    };
  });
}

function renderQuizScreen(cfg){
  quizState = {
    cfg,
    questions: prepQuestions(cfg.questions),
    submitted:false,
    timer:null,
    secondsLeft: cfg.timed ? cfg.minutes*60 : null
  };
  drawQuiz();
  if(cfg.timed) startQuizTimer();
}

function drawQuiz(){
  const qs = quizState.questions;
  const answered = qs.filter(q=>q.chosen!==null).length;
  const letters = ['A','B','C','D','E'];
  let timerHtml = '';
  if(quizState.cfg.timed && !quizState.submitted){
    timerHtml = `<div class="timer" id="timerBox">⏱ --:--</div>`;
  }
  app.innerHTML = `
    <div class="section-head">
      <h2>${quizState.cfg.title}</h2>
    </div>
    <div class="quiz-meta">
      <div class="note" style="font-family:'Space Grotesk',sans-serif; font-size:13px; color:var(--muted);">${qs.length} preguntas</div>
      ${timerHtml}
    </div>
    <div id="questionsHolder">
      ${qs.map((item,idx)=>renderQuestionCard(item, idx, letters)).join('')}
    </div>
    ${!quizState.submitted ? `
    <div class="submit-bar">
      <div class="submit-inner">
        <span class="progress-inline" id="answeredCount">${answered}/${qs.length} respondidas</span>
        <button class="btn btn-primary" onclick="submitQuiz()">Terminar cuestionario</button>
      </div>
    </div>` : renderQuizResultsFooter()}
  `;
  if(quizState.cfg.timed && !quizState.submitted) updateTimerDisplay();
}

function renderQuestionCard(item, idx, letters){
  const showReview = quizState.submitted;
  const optsHtml = item.o.map((optText,oi)=>{
    let cls = 'opt';
    if(!showReview && item.chosen===oi) cls += ' chosen';
    if(showReview){
      if(oi===item.c) cls += ' correct';
      else if(oi===item.chosen && item.chosen!==item.c) cls += ' wrong';
    }
    const inputHtml = showReview
      ? `<input type="radio" disabled ${item.chosen===oi?'checked':''}>`
      : `<input type="radio" name="q${idx}" ${item.chosen===oi?'checked':''} onchange="setAnswer(${idx},${oi})">`;
    return `<label class="${cls}">${inputHtml}<span class="letter">${letters[oi]}</span><span>${optText}</span></label>`;
  }).join('');

  let resultTag = '';
  let explainHtml = '';
  if(showReview){
    const ok = item.chosen===item.c;
    resultTag = `<span class="result-tag ${ok?'ok':'bad'}">${ok?'Correcta':'Incorrecta'}</span>`;
    explainHtml = `<div class="explain"><strong>Por qué es correcta:</strong> ${item.e}</div>`;
  }
  return `
    <div class="qcard">
      <div class="qnum">Pregunta ${idx+1} de ${quizState.questions.length}</div>
      ${resultTag}
      <div class="qtext">${item.q}</div>
      ${optsHtml}
      ${explainHtml}
    </div>
  `;
}

function setAnswer(idx, optIdx){
  quizState.questions[idx].chosen = optIdx;
  const answered = quizState.questions.filter(q=>q.chosen!==null).length;
  const counter = document.getElementById('answeredCount');
  if(counter) counter.textContent = `${answered}/${quizState.questions.length} respondidas`;
  // resaltar visualmente sin re-render completo
  const card = document.querySelectorAll('.qcard')[idx];
  if(card){
    card.querySelectorAll('.opt').forEach((el,i)=>el.classList.toggle('chosen', i===optIdx));
  }
}

function startQuizTimer(){
  clearInterval(quizState.timer);
  quizState.timer = setInterval(()=>{
    quizState.secondsLeft--;
    updateTimerDisplay();
    if(quizState.secondsLeft<=0){
      clearInterval(quizState.timer);
      submitQuiz();
    }
  },1000);
}
function updateTimerDisplay(){
  const box = document.getElementById('timerBox');
  if(!box) return;
  const s = Math.max(0, quizState.secondsLeft);
  const m = Math.floor(s/60);
  const sec = s%60;
  box.textContent = `⏱ ${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`;
  if(s<=300) box.classList.add('warn');
}

function submitQuiz(){
  if(quizState.submitted) return;
  clearInterval(quizState.timer);
  quizState.submitted = true;
  const total = quizState.questions.length;
  const correct = quizState.questions.filter(q=>q.chosen===q.c).length;
  quizState.result = {correct,total};
  if(quizState.cfg.onFinish) quizState.cfg.onFinish(correct,total);
  drawQuiz();
  window.scrollTo({top:0,behavior:'smooth'});
}

function renderQuizResultsFooter(){
  const {correct,total} = quizState.result;
  const pct = Math.round((correct/total)*100);
  const color = pct>=60 ? 'var(--teal)' : 'var(--rust)';
  return `
    <div class="score-hero">
      <div class="score-ring" style="background:conic-gradient(${color} ${pct*3.6}deg, rgba(122,74,16,0.13) 0deg);">
        <div style="background:var(--bg); width:118px; height:118px; border-radius:50%; display:flex; flex-direction:column; align-items:center; justify-content:center;">
          <div class="num">${pct}%</div>
          <div class="lbl">${correct} / ${total} correctas</div>
        </div>
      </div>
    </div>
    <div class="btn-row" style="justify-content:center;">
      ${quizState.cfg.onRepeat ? `<button class="btn btn-primary" onclick="quizState.cfg.onRepeat()">${quizState.cfg.repeatLabel||'Repetir cuestionario'}</button>` : ''}
      ${quizState.cfg.afterExtraBtn || ''}
      <button class="btn btn-secondary" onclick="goHome()">⌂ Volver al inicio</button>
    </div>
  `;
}

